import{_ as t,c as i,o as r,ag as o}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Cybersecurity","description":"","frontmatter":{"title":"Cybersecurity"},"headers":[],"relativePath":"cybersecurity/index.md","filePath":"cybersecurity/index.md","lastUpdated":null}'),s={name:"cybersecurity/index.md"};function a(n,e,c,l,p,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="cybersecurity" tabindex="-1">Cybersecurity <a class="header-anchor" href="#cybersecurity" aria-label="Permalink to &quot;Cybersecurity&quot;">​</a></h1><h2 id="cybersecurity-as-a-topic" tabindex="-1">Cybersecurity as a Topic <a class="header-anchor" href="#cybersecurity-as-a-topic" aria-label="Permalink to &quot;Cybersecurity as a Topic&quot;">​</a></h2><p>The Army defines cybersecurity as the “Prevention of damage to, protection of, and restoration of computers, electronic communications systems, electronic communications services, wire communications, and electronic communications, including information contained therein, to ensure their availability, integrity, authentication, confidentiality, and non-repudiation”.</p><p>Wikipedia defines it as:</p><p>Computer security, cybersecurity (cyber security), or information technology security (IT security) is the protection of computer systems and networks from information disclosure, theft of, or damage to their hardware, software, or electronic data, as well as from the disruption or misdirection of the services they provide. Cybersecurity helps defend against cyber attacks while improving privacy. It primarily helps defend against influence and marketing campaigns.</p><p>Cybersecurity tools, policies, and articles are often shared on the Irregular Chat at the unclassified level and derived from open source mediums.</p><h2 id="irregular-chat-cybersecurity" tabindex="-1">Irregular Chat Cybersecurity <a class="header-anchor" href="#irregular-chat-cybersecurity" aria-label="Permalink to &quot;Irregular Chat Cybersecurity&quot;">​</a></h2><ul><li><p>[Pages Tagged With “Cybersecurity”]</p></li><li><p><a href="/cybersecurity/">Resources</a></p></li><li><p><a href="https://m.youtube.com/playlist?list=PLBNtagSCmDWyUcCsdq7m5ljKYDYTNG9R1" target="_blank" rel="noreferrer">Wireshark Guide</a></p></li><li><p><a href="https://www.brimdata.io/" target="_blank" rel="noreferrer">Zed and Zuri</a> analyzing packets. Faster than Wireshark</p></li><li><p>Education</p></li></ul><h2 id="cybersecurity-terms" tabindex="-1">Cybersecurity Terms <a class="header-anchor" href="#cybersecurity-terms" aria-label="Permalink to &quot;Cybersecurity Terms&quot;">​</a></h2><p>Below are standard cybersecurity terms that may be used during conversation and recognized by industry and the government:</p><ul><li><p><strong>Adware</strong>: Free software supported by advertisements that include features such as enhanced search tools or programs such as games or utilities. The programs are free to use but require the user to watch advertisements as long as the programs are open.</p></li><li><p><strong>Antivirus Software</strong>: Uses virus definitions to determine whether a file contains a virus and must be updated regularly to protect systems and networks against new attack signatures.</p></li><li><p><strong>Attack</strong>: An intrusion against an information system (computer) resulting in the degradation, denial, or destruction of the information or information system (computer).</p></li><li><p><strong>Authentication Factor</strong>: Data used to identify an individual for access to an information system. Authentication factors can be something you know (usernames, passwords, secret questions), something you have (USB token, smart card, PKI certificate), something you are (fingerprint, DNA, retina pattern), something you do (annotating text from an image, clicking only images of storefronts), or somewhere you are (GPS location).</p></li><li><p><strong>Backdoor</strong>: Refers to any method that allows an authorized or unauthorized user to bypass some or all security measures to gain access to a computer system, network, or software application. Not all backdoors are nefarious—they can be used to assist users who become locked out of their system.</p></li><li><p><strong>Baiting</strong>: Leaving a piece of portable electronic storage media such as a CD, laptop, or USB drive near a target’s workplace to tempt the curious victim into seeing what’s on it. When the victim attempts to use the media a malware program releases a virus or exposes personal and financial information to hackers.</p></li><li><p><strong>Beacon</strong>: A type of malware that systematically calls out to a specified IP address or URL from a victimized system. A waiting threat agent can answer this beacon, establishing a connection that provides partial or even full remote access to the victimized system.</p></li><li><p><strong>Black Hat</strong>: A hacker that breaks into a network or device without consent to conduct malicious activities that can be used to harm the owner/users.</p></li><li><p><strong>Bot/Botnet</strong>: A software application or tool that performs tasks on command, allowing an attacker to control an affected computer remotely—a collection of infected computers is a botnet.</p></li><li><p><strong>Brute Force Attack</strong>: A programming style that does not include any shortcuts to improve performance but relies on sheer computing power to try all possibilities until the solution to a problem is found.</p></li><li><p><strong>Cache</strong>: Contains copies of web pages saved by the browser that was used to view them. These files are used to increase web browsing speed and are sometimes called temporary internet files.</p></li><li><p><strong>Ciphertext</strong>: The unreadable, unintelligible group of alphanumeric characters produced from a cipher (an algorithm for performing encryption or decryption) or the input to an inverse cipher.</p></li><li><p><strong>Clickjacking</strong>: An attack that tricks victims into clicking on a disguised link, potentially causing the victim to reveal confidential information or allowing others access to the victim’s system.</p></li><li><p><strong>Client</strong>: A host seeking to use a server’s resources.</p></li><li><p><strong>Client/Server Network</strong>: In this network, individual workstations send requests to a central server, and the server provides all resources.</p></li><li><p><strong>Cloud</strong>: A collection of computers with large storage capabilities that remotely serve requests, allowing you to access files and services online from anywhere in the world.</p></li><li><p><strong>Computer Network Exploitation (CNE)</strong>: Consists of techniques and processes that use computers or computer networks to gather data on targeted systems and networks.</p></li><li><p><strong>Cookie</strong>: An information packet sent from a website to a web browser that records a user’s activity on that website. The information packet is stored on the user’s computer and used to provide more personalized services for each subsequent visit to the website.</p></li><li><p><strong>Cracking</strong>: When an attacker generates a set of values representing possible legitimate authentication factors and then tests those values against the authentication system to see which is correct.</p></li><li><p><strong>Cross-site Scripting (XSS)</strong>: Occurs when an attacker sends a script that is executed by a victim system’s web browser or in another browser window accessing a different site.</p></li><li><p><strong>Cryptocurrency</strong>: Any digital currency that uses an online ledger and cryptography to secure transactions.</p></li><li><p><strong>Cryptography</strong>: The discipline that embodies the principles, means, and methods for the transformation of data to hide their semantic content, prevent their unauthorized use, or prevent their undetected modification.</p></li><li><p><strong>Dark Web</strong>: A subset of the deep web. Its content is not indexed and consists of overlaying networks that use the public internet but require unique software, configuration, or authorization to access; designed to hide the identity of the user. Commonly contains anonymous journalism and marketplaces for illegal goods and services, and is regularly used by threat actors.</p></li><li><p><strong>Decryption</strong>: The process of transforming ciphertext into plain text.</p></li><li><p><strong>Deepfake</strong>: An audio or video clip edited and manipulated to seem real.</p></li><li><p><strong>Deep Web</strong>: Online content that is not indexed by traditional search engines. The content is available to the general public but is harder to find unless you have the exact URL. Legitimate uses of the deep web include online banking, web mail, cloud storage, and legal documents.</p></li><li><p><strong>Denial of Service (DoS)</strong>: An attack that inhibits a computer resource from communicating on a network, preventing it from being available to fulfill its purpose either temporarily or permanently.</p></li><li><p><strong>Directory</strong>: A centralized listing of resources such as users, groups, files, and applications. Directories are also known as folders.</p></li><li><p><strong>Distributed Denial of Service (DDoS)</strong>: A DoS attack that is sourced/distributed from many different host systems. It involves using computers to flood a single target simultaneously, causing a denial-of-service condition.</p></li><li><p><strong>DNS</strong>: Domain Name System is a hierarchical naming system built on a distributed database. This system transforms domain names to IP addresses and makes it possible to assign domain names to groups of Internet resources and users, regardless of the entities’ physical location.</p></li><li><p><strong>DNS Hijacking</strong>: A malicious exploit in which a hacker or other party redirects users through a rogue DNS server or other strategy that changes the IP address to which an Internet user is directed.</p></li><li><p><strong>Domain Name</strong>: A text-based translation of the numerical IP address assigned to an internet resource. Domain names are also referred to as internet addresses.</p></li><li><p><strong>Doxxing</strong>: The process of gathering information about a person or business using online public sources such as social media profiles, reverse phone lookup, and search engines. Doxxing typically leads to an anonymous person’s identity being revealed.</p></li><li><p><strong>Encryption</strong>: The conversion of plain text to ciphertext through the use of a cryptographic algorithm. Encryption is commonly used to ensure the confidentiality and integrity of electronic communications and is a direct application of cryptography.</p></li><li><p><strong>Exploit</strong>: A malicious application/tool used to take advantage of a system’s vulnerabilities.</p></li><li><p><strong>Firewall</strong>: An access control device (can be software or hardware) that performs specific security activities such as detecting failed attempts at access.</p></li><li><p><strong>Hacker</strong>: An unauthorized user who attempts to or gains access to an information system, the act of which is known as hacking.</p></li><li><p><strong>Hacktivist</strong>: Formed by combining “hack” with “activism,” hacktivism is the act of hacking into a website or computer system to communicate a politically or socially motivated message. For the hacktivist, it is more about making a statement than causing harm.</p></li><li><p><strong>Identity Theft</strong>: A crime in which an attacker uses the stolen identity of another individual to gain access to financial resources and/or other privileges.</p></li><li><p><strong>Intrusion Detection System (IDS)</strong>: A system that monitors network and/or system activities for malicious activities or policy violations and produces reports to a management station. An IDS can identify both internal and external threats and is used to detect and mitigate potential security breaches.</p></li><li><p><strong>Intrusion Prevention System (IPS)</strong>: A network security device that inspects traffic and performs actions to block or prevent malicious traffic from reaching its intended destination.</p></li><li><p><strong>Malware</strong>: Malicious software, including viruses, worms, trojans, and other programs designed to damage or disrupt systems or information. Malware often spreads without the knowledge or consent of the victim.</p></li><li><p><strong>Password</strong>: A string of characters used to authenticate a user. To be effective, passwords should be long and contain a mix of letters, numbers, and symbols.</p></li><li><p><strong>Penetration Testing (Pentest)</strong>: The process of simulating an attack on an information system to identify and exploit vulnerabilities, typically used to assess the security posture of the system.</p></li><li><p><strong>Phishing</strong>: A social engineering attack that attempts to trick victims into divulging personal information such as usernames, passwords, or financial information by pretending to be a legitimate entity or individual.</p></li><li><p><strong>Public Key Infrastructure (PKI)</strong>: A framework for managing digital certificates and encryption keys to secure communications and verify identities in a networked environment.</p></li><li><p><strong>Ransomware</strong>: A type of malware that encrypts a victim’s files or locks them out of their system until a ransom is paid to the attacker.</p></li><li><p><strong>Social Engineering</strong>: The manipulation of individuals into revealing confidential or personal information that can be used for fraudulent purposes.</p></li><li><p><strong>Spyware</strong>: Software designed to gather information about a user or system without their knowledge or consent and transmit that information to a third party.</p></li><li><p><strong>Virus</strong>: A type of malicious software that replicates by inserting copies of itself into other programs or files. It can spread to other systems and may cause damage to the affected systems.</p></li><li><p><strong>Vulnerability</strong>: A weakness in a system or network that can be exploited by a threat actor to gain unauthorized access or cause harm.</p></li><li><p><strong>Zero-Day Exploit</strong>: An attack that takes advantage of a previously unknown vulnerability in software or hardware, before the vendor has issued a fix or patch for the vulnerability.</p></li></ul><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2>',12)])])}const g=t(s,[["render",a]]);export{h as __pageData,g as default};
